function stop(keepFullscreen=false){PetNails.stop();PetAccessories.stop();run++;cancelAnimationFrame(frame);timers.forEach(clearTimeout);timers=[];release();state=null;if(ownFull&&!keepFullscreen){ownFull=false;try{screen.orientation?.unlock();document.exitFullscreen()?.catch(()=>{});}catch{}}}
function later(fn,ms){const id=run;timers.push(setTimeout(()=>{if(id===run&&state)fn();},ms));}
function sparkle(index,all=false){const host=q('.pet-cat');if(!host)return;const pos=regions()[index]||[50,50];for(let i=0;i<(all?22:6);i++){const star=document.createElement('span');star.className='pet-glitter';star.textContent='✦';star.style.cssText='left:'+(all?8+Math.random()*84:pos[0]+(Math.random()-.5)*20)+'%;top:'+(all?Math.random()*95:pos[1]+(Math.random()-.5)*15)+'%;animation-delay:'+i*.04+'s';host.append(star);later(()=>star.remove(),1600);}}
function renderCat(){hintKey='';let expression=state.stage==='done'?'feliz':PetCore.isWet(state)?'molhado':state.arched?'bravo-arqueado':state.mood==='angry'?'bravo-sentado':state.mood==='sad'?'triste':'feliz';q('.pet-animal').src=base+catFile(expression);q('.pet-cat').classList.toggle('arched',state.arched);q('.pet-cat').classList.toggle('pet-dog',PetCore.isDog(state.breed));const positions=regions();q('.pet-regions').innerHTML=positions.map((p,i)=>{const c=(PetCore.isDog(state.breed)?dogCrops:crops)[i];return '<button class="pet-region" data-zone="'+i+'" aria-label="Cuidar da região '+(i+1)+'" style="left:'+p[0]+'%;top:'+p[1]+'%;width:'+p[2]+'%;height:'+p[3]+'%"><svg class="pet-dirt" viewBox="'+c.join(' ')+'" aria-hidden="true"><image href="'+base+dirtFile()+'" width="1145" height="1374"/></svg><img class="pet-foam" src="'+base+'espuma-v1.webp" alt=""></button>';}).join('');q('.pet-regions').querySelectorAll('button').forEach(b=>{b.onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();if(tool==='treat'){feed();return;}held=true;active=+b.dataset.zone;}};b.onkeyup=release;b.onblur=release;});update();}
function update(){if(!state)return;const done=state.progress.filter(p=>p>=1).length;if(PetCore.isWet(state)&&!q('.pet-animal').src.endsWith(catFile('molhado')))q('.pet-animal').src=base+catFile('molhado');q('#pet-message').textContent=state.feeding?'Nhac, nhac… que delícia!':state.arched?'Ele se assustou! Ofereça um biscoito para acalmar.':instructions[state.stage];q('#pet-count').textContent=state.stage==='done'?'Muito bem!':done+' / 9 regiões';q('.pet-total-fill').style.width=(state.stage==='done'?100:done/9*100)+'%';q('.pet-steps').innerHTML=['Molhar','Ensaboar','Enxaguar','Secar'].map((s,i)=>'<span class="'+(['rinse','soap','rinseSoap','dry'].indexOf(state.stage)===i?'current':'')+'">'+(i+1)+' · '+s+'</span>').join('');q('.pet-regions').querySelectorAll('button').forEach((b,i)=>{const p=state.progress[i];b.classList.toggle('complete',p>=1);b.disabled=state.stage==='done';b.querySelector('.pet-dirt').style.opacity=state.stage==='rinse'?1-p:0;b.querySelector('.pet-foam').style.opacity=state.stage==='soap'?p:state.stage==='rinseSoap'?1-p:0;b.setAttribute('aria-label','Região '+(i+1)+', '+Math.round(p*100)+'%');});q('.pet-hint').textContent=state.stage==='done'?'Pronto para mais um amigo?':tool==='treat'?'Toque no bichinho para oferecer o biscoito.':(tool==='soap'?'Movimente o sabonete em qualquer direção · ':tool==='shower'?'Segure a ducha sobre cada região · ':'Segure o secador sobre cada região · ')+String(PetCore.durations[state.stage]/1000).replace('.',',')+'s por região';}
function select(next){if(state&&next!==tool&&(next===PetCore.expected[state.stage]||(state.mood==='angry'&&next==='treat')))lastProgress=performance.now();release();tool=next;q('.pet-tools').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.tool===tool));q('.pet-cursor-tool').src=base+toolFile(tool);q('.pet-cursor').dataset.tool=tool;update();}
function feed(){if(state.feeding||state.stage==='done')return;release();lastProgress=performance.now();state.feeding=true;const bite=q('.pet-snack');bite.hidden=false;bite.src=base+snackFile();update();later(()=>bite.src=base+snackFile('mordido-30'),650);later(()=>bite.src=base+snackFile('mordido-70'),1300);later(()=>{bite.hidden=true;lastProgress=performance.now();PetCore.calm(state);renderCat();select(PetCore.expected[state.stage]);tone();},2000);}
function position(e){
 const stage=q('.pet-play'),r=stage.getBoundingClientRect(),cursor=q('.pet-cursor');
 // Touch events need finger clearance on tablets too, regardless of viewport size.
 const portrait=stage.classList.contains('pet-portrait'),mobile=(e.pointerType==='touch'||matchMedia('(max-height:520px),(max-width:700px)').matches)&&tool!=='treat';
 cursor.hidden=false;
 // Choose the hand in game coordinates, and keep it stable throughout the drag.
 const fingerX=portrait?e.clientY-r.top:e.clientX-r.left,gameWidth=portrait?r.height:r.width;
 if(mobile&&!held)handSide=fingerX>gameWidth/2?'right':'left';
 const right=mobile&&handSide==='right';
 cursor.classList.toggle('pet-right-hand',right);
 const distance=mobile?(tool==='soap'?120:tool==='shower'?90:cursor.offsetWidth*1.15):0;
 const target=PetCore.offsetPoint(e.clientX,e.clientY,portrait,mobile,right?-distance:distance);
 let x=target.x-r.left,y=target.y-r.top;
 if(portrait){x=target.y-r.top;y=r.right-target.x;}
 cursor.style.left=x+'px';cursor.style.top=y+'px';
 const el=document.elementFromPoint(target.x,target.y)?.closest('[data-zone]');active=el?+el.dataset.zone:-1;
 if(held){const bounds=el?.getBoundingClientRect(),size=bounds?Math.max(24,Math.min(bounds.width,bounds.height)):1;motionCredit=Math.min(80,motionCredit+PetCore.movement(gesture,target.x/size,target.y/size,performance.now(),active));}
}
function tick(now){if(!state)return;const dt=PetCore.elapsedForTool(tool,now-last,motionCredit);motionCredit=0;last=now;q('.pet-cursor')?.classList.toggle('working',held&&now-lastProgress<120);idleHint(now);if(state.ready&&held&&active>=0&&!document.hidden&&(dt>0||state.mood==='angry')){const index=active,result=PetCore.touch(state,tool,index,dt);if(result==='angry'){release();renderCat();}else if(['region','stage','finished'].includes(result)){lastProgress=now;tone(result==='finished');if(result!=='region'){release();renderCat();if(result==='stage')select(PetCore.expected[state.stage]);}else update();sparkle(index,result==='finished');if(result==='finished'){PetNails.mount({breed:state.breed,onClip:()=>tone(),onComplete:()=>{tone(true);PetAccessories.mount({breed:state.breed,onNext:start,onPlace:()=>tone()});}});}}else if(result==='working'){lastProgress=now;update();q('.pet-cursor').classList.add('working');}}frame=requestAnimationFrame(tick);}
function idleHint(now){const show=state.ready&&!state.feeding&&state.stage!=='done'&&now-lastProgress>=4000;const zone=show?state.progress.findIndex(p=>p<1):-1;const needed=show?(state.mood==='angry'?'treat':PetCore.expected[state.stage]):'';const key=zone+':'+needed;if(key===hintKey)return;hintKey=key;q('.pet-regions')?.querySelectorAll('button').forEach((b,i)=>b.classList.toggle('pet-needs-care',i===zone));q('.pet-tools')?.querySelectorAll('button').forEach(b=>b.classList.toggle('pet-needs-tool',b.dataset.tool===needed&&(needed!==tool||state.mood==='angry')));}
function enterFullscreen(){
 if(document.fullscreenElement||!document.documentElement.requestFullscreen)return;
 try{Promise.resolve(document.documentElement.requestFullscreen()).then(()=>{
  if(!state||!q('.pet-play')){if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});return;}
  ownFull=!!document.fullscreenElement;
  if(ownFull){try{Promise.resolve(screen.orientation?.lock?.('landscape')).catch(()=>{});}catch{}}
  resize();
 }).catch(()=>{resize();});}catch{resize();}
}
function resize(){const s=q('.pet-play');if(!s)return;const w=visualViewport?.width||innerWidth,h=visualViewport?.height||innerHeight;s.style.setProperty('--pw',w+'px');s.style.setProperty('--ph',h+'px');s.classList.toggle('pet-portrait',w<h&&w<700);}
function preload(){const id=run;state.ready=false;const stage=q('.pet-play');stage.classList.add('loading');const overlay=document.createElement('div');overlay.className='pet-loading';overlay.innerHTML='<strong>Preparando um banho de carinho…</strong>';stage.append(overlay);const assets=['feliz','triste','molhado','bravo-sentado','bravo-arqueado'].map(catFile).concat([dirtFile(),snackFile(),snackFile('mordido-30'),snackFile('mordido-70'),'espuma-v1.webp','vento-secador-v1.webp','agua-ducha-v1.webp','sabonete-v1.webp','ducha-v1.webp','secador-v1.webp']).concat(PetAccessories.items.map(i=>i.id+'-v1.webp'),['cordao-capa-roxa-v1.webp','cordao-capa-azul-v1.webp']);Promise.all(assets.map(file=>new Promise((resolve,reject)=>{const image=new Image(),timeout=setTimeout(()=>reject(new Error(file)),20000);image.onload=()=>{clearTimeout(timeout);image.decode().then(resolve,reject);};image.onerror=()=>{clearTimeout(timeout);reject(new Error(file));};image.src=base+file;}))).then(()=>{if(id!==run||!state)return;state.ready=true;lastProgress=performance.now();stage.classList.remove('loading');overlay.remove();}).catch(()=>{if(id!==run||!state)return;overlay.innerHTML='<strong>Uma imagem não carregou.</strong><button>Tentar novamente</button>';overlay.querySelector('button').onclick=()=>{overlay.remove();preload();};});}
